// n8n Function Item

// 1) El "body" es simplemente el JSON del item
let body = item.json || {};

// 2) Tomar el SQL desde las PascalCase (o alternativas si algún día cambia)
let rawSql =
  body.SqlEjecutado ??
  body.QueryDeOperacion ??
  body.Query ??
  body.query ??
  '';

// 3) Asegurar que sea string
if (typeof rawSql !== 'string') {
  try { rawSql = JSON.stringify(rawSql); }
  catch (e) { rawSql = String(rawSql); }
}

// 4) Limpieza HTML / entidades / espacios
let sql = rawSql
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<p[^>]*>/gi, '')
  .replace(/<[^>]*>/g, '')
  .replace(/(&nbsp;|&lt;|&gt;|&amp;|&#39;|&quot;)/g, m => ({
    '&nbsp;': ' ',
    '&lt;': '<',
    '&gt;': '>',
    '&amp;': '&',
    '&#39;': "'",
    '&quot;': '"'
  })[m])
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

// 5) Inferir operación
const opMatch = /^\s*(update|insert|delete|merge|select)\b/i.exec(sql || '');
const Operacion = opMatch
  ? opMatch[1].toUpperCase()
  : (body.Operacion?.toUpperCase?.() || 'UNKNOWN');

// 6) Salida con todas tus PascalCase + Agregado AsignadoPara
const out = {
  CasoId:        body.CasoId ?? null,
  Cliente:       body.Cliente ?? null,
  BaseDeDatos:   body.BaseDeDatos ?? null,
  SqlEjecutado:  sql,
  Operacion,
  UrlCaso:       body.UrlCaso ?? null,
  TituloCaso:    body.TituloCaso ?? null,
  CreadoPor:     body.CreadoPor ?? null,
  AsignadoPara:  body.AsignadoPara ?? body.asignadoPara ?? null,  // 👈 NUEVO
  EjecucionEn:   new Date().toISOString()
};

// 7) Return (un solo item)
return out;

// Function (procesa todos los items de entrada y devuelve { text } por item)

// --- Utilidades ---
function stripHtml(input) {
  if (input == null) return '';
  let s = String(input);
  s = s.replace(/<br\s*\/?>/gi, '\n')
       .replace(/<\/p>/gi, '\n')
       .replace(/<p[^>]*>/gi, '');
  s = s.replace(/<[^>]*>/g, '');
  s = s.replace(/(&nbsp;|&lt;|&gt;|&amp;|&#39;|&quot;)/g, m => ({
    '&nbsp;':' ', '&lt;':'<', '&gt;':'>', '&amp;':'&', '&#39;':"'", '&quot;':'"'
  })[m]);
  return s;
}

function normalizeQuery(q) {
  if (q == null) return '';
  if (Array.isArray(q)) q = q.join('\n');
  if (typeof q !== 'string') { try { q = JSON.stringify(q); } catch { q = String(q); } }
  q = stripHtml(q);
  q = q.replace(/`{3,}/g, '');
  q = q.replace(/[\u2000-\u200A\u202F\u205F\u3000]/g, ' ')
       .replace(/\r\n?/g, '\n');
  q = q.replace(/\(\s+/g, '(')
       .replace(/\s+\)/g, ')')
       .replace(/[ \t]+\n/g, '\n')
       .replace(/\n{3,}/g, '\n\n');
  q = q.split(';').map(s => s.trim()).filter(Boolean).join('\n');
  q = q.replace(/[ \t]{2,}/g, ' ').trim();
  q = q.replace(/<\/?[^>]+>$/g, '').trim();
  return q;
}

return items.map(({ json }) => {
  // Variables esperadas en PascalCase
  const CasoId       = json?.CasoId ?? '';
  const Cliente      = json?.Cliente ?? '';
  const BaseDeDatos  = json?.BaseDeDatos ?? '';
  const SqlEjecutado = normalizeQuery(json?.SqlEjecutado ?? '');
  const Operacion    = (json?.Operacion ?? '').toString().toUpperCase();
  const UrlCaso      = json?.UrlCaso ?? '';
  const TituloCaso   = json?.TituloCaso ?? '';
  const CreadoPor    = json?.CreadoPor ?? '';
  const AsignadoPara    = json?.AsignadoPara ?? '';   // <-- NUEVO CAMPO

  const metaLines = [
    `- **ID del Caso:** ${CasoId}`,
    TituloCaso   ? `- **Título del Caso:** ${TituloCaso}` : null,
    Cliente      ? `- **Cliente:** ${Cliente}` : null,
    BaseDeDatos  ? `- **Base de Datos:** ${BaseDeDatos}` : null,
    Operacion    ? `- **Operación:** ${Operacion}` : null,
    AsignadoPara    ? `- **Asignado a:** ${AsignadoPara}` : null,  // <-- 
    UrlCaso      ? `- **URL de Referencia:** (${UrlCaso})` : null,
    CreadoPor    ? `- **Creado por:** ${CreadoPor}` : null
  ].filter(Boolean);

  const bloques = [];
  if (SqlEjecutado) {
    bloques.push(
      '- **SQL Ejecutado:**',
      '```sql',
      SqlEjecutado,
      '```'
    );
  }

  const md = [
    '📢 Notificación de Caso DevOps – Soporte de Operación',
    '',
    ...metaLines,
    '',
    ...bloques
  ].join('\n');

  const mdLimpio = md.replace(/<\/p>/gi, '').trim();

  return { json: { text: mdLimpio } };
});

